int f(int[] a, int lo, int hi) {
  if (hi - lo < 1) return a[lo];          // one element
  int mid = (lo + hi) / 2;
  int x = f(a, lo, mid);
  int y = f(a, mid + 1, hi);
  int z = f(a, lo, mid);                   // yes, again
  for (int i = lo; i <= hi; i++) x += a[i];
  return x + y + z;
}
